								return
							end

							-- bee type -> tokens it makes that "Priority Tokens" can target
							local tokens = {
								Cool = { "Blue Boost" },
								Bucko = { "Blue Boost" },
								Frosty = { "Blue Boost" },
								Diamond = { "Blue Boost" },
								Tadpole = { "Blue Boost", "Summon Frog" },
								Buoyant = { "Inflate Balloon" },
								Ninja = { "Haste" },
								Hasty = { "Haste" },
								Shocked = { "Haste" },
								Photon = { "Haste" },
								Baby = { "Baby Love" },
								Music = { "Melody", "Focus" },
								Commander = { "Focus" },
								Looker = { "Focus" },
								Fuzzy = { "Fuzz Bombs" },
								Vector = { "Triangulate" },
								Carpenter = { "Pollen Mark" },
								Honey = { "Honey Mark" }
							}

							-- gifted bee -> the hive-bonus token only a gifted copy unlocks
							local gifted = { Buoyant = "Surprise Party", Tadpole = "Baby Love", Fuzzy = "Pollen Haze", Vector = "Mark Surge" }

							-- every blue bee on the wiki, so "hive read fine" can be told from "type names changed"
							local blue = {
								Bumble = true, Cool = true, Bubble = true, Bucko = true, Frosty = true, Diamond = true,
								Ninja = true, Buoyant = true, Tadpole = true, Cobalt = true, Vicious = true
							}

							local count, known = 0, 0
							local have, haveGifted = {}, {}

							for _, col in pairs(comb) do
								if type_(col) == "table" then
									for _, bee in pairs(col) do
										if type_(bee) == "table" and type_(bee.Type) == "string" then
											local kind = bee.Type

											count = count + 1
											have[kind] = true

											if blue[kind] or tokens[kind] or gifted[kind] then
												known = known + 1
											end

											if type_(bee.Traits) == "table" then
												for _, trait in ipairs(bee.Traits) do
													if trait == "Gifted" then
														haveGifted[kind] = true
													end
												end
											end
										end
									end
								end
							end

							-- hive unreadable or type names do not match the wiki -> write nothing
							if count == 0 or known == 0 then
								return
							end

							-- a copy of the current settings; the live ones are never changed
							local cfg = HttpService:JSONDecode(HttpService:JSONEncode(t12))
							local af = cfg.autofarm

							if type_(af) ~= "table" then
								return
							end

							-- blue fields this hive may enter, best first
							local need = { ["Pine Tree Forest"] = 15, ["Bamboo Field"] = 5, ["Blue Flower Field"] = 0 }
							local usable = {}

							for _, name in ipairs({ "Pine Tree Forest", "Bamboo Field", "Blue Flower Field" }) do
								if count >= need[name] then
									usable[#usable + 1] = name
								end
							end

							af.enabled = true
							af.multiplefields = false
							af.field1 = usable[1]
							af.field2 = usable[2] or usable[1]
							af.field3 = usable[3] or usable[#usable]

							if type_(cfg.autoquest) == "table" then
								cfg.autoquest.bestbluefield = usable[1]
							end

							if type_(cfg.rbc) == "table" then
								cfg.rbc.preset = "Blue"
								cfg.rbc.bestbluefield = usable[1]
							end

							-- token priorities this hive can really produce (additive, nothing is removed)
							if type_(af.priority) ~= "table" then
								af.priority = {}
							end

							local added = {}

							local function want(tok)
								if not af.priority[tok] then
									af.priority[tok] = true
									added[#added + 1] = tok
								end
							end

							want("Blue Boost")

							for kind in pairs(have) do
								for _, tok in ipairs(tokens[kind] or {}) do
									want(tok)
								end

								if gifted[kind] and haveGifted[kind] then
									want(gifted[kind])
								end
							end

							-- bubbles (Bubble Bee, Tadpole Bee) and balloons (Buoyant Bee)
							if have.Bubble or have.Tadpole then
								af.bubbles = true

								if type_(cfg.face) == "table" then
									cfg.face.bubbles = true
								end
							end

							if have.Buoyant then
								af.balloons = true
							end

							if have.Baby and type_(cfg.combat) == "table" then
								cfg.combat.babylove = true
							end

							-- the Blue Field Booster is the blue booster
							if type_(cfg.boosters) == "table" then
								cfg.boosters.enabled = true

								if type_(cfg.boosters.allowed) ~= "table" then
									cfg.boosters.allowed = {}
								end

								cfg.boosters.allowed["Blue Field Booster"] = true
							end

							-- nectar: Pine Tree Forest / Bamboo Field give Comforting, Blue Flower Field gives Refreshing
							local nectar = type_(cfg.planters) == "table" and cfg.planters.nectar

							if type_(nectar) == "table" then
								nectar.comfortinglastfield = count >= 15 and "Pine Tree Forest" or (count >= 5 and "Bamboo Field" or nectar.comfortinglastfield)
								nectar.refreshinglastfield = "Blue Flower Field"
							end

							writefile("atlas1/BlueTeam.json", HttpService:JSONEncode(cfg))
							print("[bluepreset] atlas1/BlueTeam.json | " .. count .. " bees | " .. tostring(af.field1) .. " / " .. tostring(af.field2) .. " / " .. tostring(af.field3) .. " | +tokens: " .. (#added > 0 and table.concat(added, ", ") or "none"))
						end)
					end)
				end

