				function t2.rj.find()
					if not (isfile and readfile) then
						return
					end

					local names = {}

					if _G.AtlasLocalScript then
						names[#names + 1] = _G.AtlasLocalScript
					end

					for _, p in ipairs({
						"atlas1/atlas.lua",
						"atlas.lua",
						"atlas1_2_-_40.blue.lua",
						"atlas1/atlas1_2_-_40.blue.lua",
						"atlas1/atlas_blue.lua",
						"atlas1/atlas_red.lua",
						"atlas_red.lua",
						"atlas1_2_-_40.red.lua"
					}) do
						names[#names + 1] = p
					end

					for _, p in ipairs(names) do
						local ok, exists = pcall(isfile, p)

						if ok and exists then
							return p
						end
					end

					-- last resort: any atlas*blue*.lua / atlas*red*.lua in the workspace root or in atlas1/
					if listfiles then
						for _, dir in ipairs({
							".",
							"atlas1"
						}) do
