	-- "Bee To Find": tap the bee you are LOOKING FOR, then choose the mutation it must have.
	-- Auto Mutations rolls the bees you picked in Select Position (the ones you can throw away) until one becomes
	-- a bee you are looking for AND has that bee's mutation. Nothing here selects or rolls any other bee.
	-- stored as hive.typemutas["Spicy"] = { [mutation] = { enabled, minimum } }  (same shape as hive.mutations2)
	-- a type with nothing enabled falls back to the global "Configure Mutations" list.
	-- saved in the preset AND in atlas1/typemutas.json (loaded at start-up, so it survives preset switches and rejoins).
	t222.TypeMutations = function(p645, p646, p647)
		local per = p646[p647]

		if not per or type_(per) ~= "table" then
			per = {}
			p646[p647] = per
		end

		local function hasTarget(cfg)
			if type_(cfg) == "table" then
				for _, v in pairs(cfg) do
					if type_(v) == "table" and v[1] then
						return true
					end
				end
			end

			return false
		end

		-- the persistent copy only keeps types that really have a target
		local function saveFile()
			pcall(function()
				local out = {}

				for name, cfg in pairs(per) do
					if hasTarget(cfg) then
						out[name] = cfg
					end
				end

				writefile("atlas1/typemutas.json", HttpService:JSONEncode(out))
			end)
		end

		local function save()
			pcall(function()
				writefile("atlas1/" .. u63 .. ".json", HttpService:JSONEncode(t12))
			end)
			saveFile()
		end

		-- how many bees of each type are in the hive right now
		local owned = {}
		local honeycomb = u61(ClientStatCache.Get, nil, "Honeycomb")

		if type_(honeycomb) == "table" then
			for _, col in pairs(honeycomb) do
				if type_(col) == "table" then
					for _, bee in pairs(col) do
						if type_(bee) == "table" and bee.Type then
							owned[bee.Type] = (owned[bee.Type] or 0) + 1
						end
					end
				end
			end
		end

		local searchBox = p645:FindFirstChild("TextBox")

		if searchBox then
			searchBox:Destroy()
		end

		local section = {
			Box = p645
		}
		local header = t7.ha:Clone()

		header.Name = "Header"
		header.Size = UDim2.new(1, 0, 0, 4)
		header.Parent = p645

		-- what is saved right now (so it is obvious that your choices were kept)
		local function summary()
			local parts = {}

			for name, cfg in pairs(per) do
				if hasTarget(cfg) then
					parts[#parts + 1] = name
				end
			end

			table.sort(parts)

			return #parts > 0 and ("Looking for: " .. table.concat(parts, ", ")) or "Looking for: nothing yet"
		end

		local saved = v3581(summary(), section, true)

		v3581("Tap the bee you are looking for, then pick the mutation it needs (at the bottom). The bees you roll are the ones picked in Select Position.", section, true)

		-- bee types: rarest first, then by name
		local rank = {
			Mythic = 1,
			Legendary = 2,
			Epic = 3,
			Rare = 4,
			Common = 5,
			Event = 6
		}
		local list = {}

		for name in pairs(t11.BeeTypes) do
			list[#list + 1] = name
		end

		table.sort(list, function(a, b)
			local ra = rank[t11.BeeTypes[a].Rarity] or 9
			local rb = rank[t11.BeeTypes[b].Rarity] or 9

			if ra ~= rb then
				return ra < rb
			end

			return a < b
		end)

		local grid = instanceNew("Frame")

		grid.AutomaticSize = Enum.AutomaticSize.XY
		grid.BackgroundTransparency = 1
		grid.BorderSizePixel = 0
		grid.Parent = p645

		local layout = instanceNew("UIGridLayout")

		layout.CellSize = UDim2.fromOffset(48, 48)
		layout.CellPadding = UDim2.fromOffset(4, 4)
		layout.FillDirectionMaxCells = 5
		layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Parent = grid

		local info = v3581("", section, true)
		local cells = {}
		local rows = {}
		local current
		local buildRows

		local function refresh(name)
			local ui = cells[name]

			if ui then
				ui.badge.Visible = hasTarget(per[name])
			end

			saved.Text = summary()
		end

		-- "Spicy (Mythic)  in hive: 3" + what it is currently set to roll for
		local function describe(name)
			local parts = {}
			local cfg = per[name]

			if type_(cfg) == "table" then
				for mname, entry in pairs(cfg) do
					if type_(entry) == "table" and entry[1] then
						local mt = t11.BeeMutationTypes[mname]

						parts[#parts + 1] = (mt and mt.DisplayName or mname) .. " >= " .. tostring(entry[2])
					end
				end
			end

			table.sort(parts)

			return name .. " (" .. tostring(t11.BeeTypes[name].Rarity) .. ")  in hive: " .. tostring(owned[name] or 0) .. "\n" .. (#parts > 0 and ("wants: " .. table.concat(parts, ", ")) or "no mutation set: uses the global list")
		end

		local function pick(name)
			local ui = cells[name]

			if not ui then
				return
			end

			current = name

			for n, other in pairs(cells) do
				other.button.BorderSizePixel = n == name and 2 or 0
			end

			info.Text = describe(name)
			buildRows(name)

			-- bring the mutation rows into view
			spawn(function()
				wait()
				pcall(function()
					local y = info.AbsolutePosition.Y - p645.AbsolutePosition.Y + p645.CanvasPosition.Y - 4

					p645.CanvasPosition = Vector2.new(0, math.max(0, y))
				end)
			end)
		end

		v3584("Reset This Type", section, function()
			if current then
				per[current] = nil
				refresh(current)
				info.Text = describe(current)
				save()
				buildRows(current)
			end
		end)

		buildRows = function(name)
			for _, inst in ipairs(rows) do
				inst:Destroy()
			end

			rows = {}

			local cfg = per[name]

			if not cfg or type_(cfg) ~= "table" then
				cfg = {}
				per[name] = cfg
			end

			local mnames = {}

			for mname in pairs(t11.BeeMutationTypes) do
				mnames[#mnames + 1] = mname
			end

			table.sort(mnames)

			local sliders = {}

			for _, mname in ipairs(mnames) do
				local mt = t11.BeeMutationTypes[mname]
				local lo = mt.MinValue[1]
				local hi = mt.MaxValue[2]
				local entry = cfg[mname]

				if not entry or type_(entry) ~= "table" then
					entry = {
						false,
						lo
					}
					cfg[mname] = entry
				end

				local toggle = v3585((mt.Op == "Mul" and "x " or "+ ") .. mt.DisplayName, section, function()
					refresh(name)

					if current == name then
						info.Text = describe(name)
					end

					saveFile()
				end, entry, 1, nil, true)

				toggle.Instance.Size = UDim2.new(1, -15, 0, 20)
				t5.ToggleSwitch(toggle, entry[1], true)
				table.insert(rows, toggle.Instance)

				local minimum = v3720("Minimum", section, function()
					if current == name then
						info.Text = describe(name)
					end

					saveFile()
				end, lo, hi, entry, 2, {
					Left = true,
					Res = mt.Interval
				})

				minimum.Instance.Size = UDim2.new(1, -15, 0, 20)
				table.insert(rows, minimum.Instance)
				sliders[#sliders + 1] = {
					minimum,
					entry
				}
			end

			-- sliders need one frame of layout before their bar can be drawn
			spawn(function()
				wait()

				for _, s in ipairs(sliders) do
					if s[1].Instance.Parent then
						t5.SetSlider(s[1], s[2][2], nil, true)
					end
				end
			end)
		end

		local colors = {
			None = Color3.fromRGB(27, 42, 53),
			Red = Color3.fromRGB(234, 75, 71),
			Blue = Color3.fromRGB(91, 159, 237)
		}

		for i, name in ipairs(list) do
			local beeType = t11.BeeTypes[name]
			local button = instanceNew("ImageButton")

			button.AutoButtonColor = false
			button.BackgroundColor3 = beeType.RarityColor3
			button.BorderSizePixel = 0
			button.BorderColor3 = Color3.fromRGB(255, 255, 255)
			button.LayoutOrder = i
			button.Image = beeType.FaceOutline

			if not beeType.PrecoloredFace then
				button.ImageColor3 = colors[beeType.ColorType] or colors.None
			end

			button.Parent = grid

			-- "xN" = how many of this type are in the hive
			local count = instanceNew("TextLabel")

			count.BackgroundTransparency = 1
			count.Font = Enum.Font.GothamBold
			count.Text = "x" .. tostring(owned[name] or 0)
			count.TextColor3 = Color3.fromRGB(255, 255, 255)
			count.TextSize = 11
			count.TextStrokeTransparency = 0
			count.TextXAlignment = Enum.TextXAlignment.Left
			count.TextYAlignment = Enum.TextYAlignment.Top
			count.Position = UDim2.fromOffset(2, 0)
			count.Size = UDim2.fromOffset(24, 14)
			count.Visible = (owned[name] or 0) > 0
			count.Parent = button

			-- "M" = this type has its own mutation target
			local badge = instanceNew("TextLabel")

			badge.AnchorPoint = Vector2.new(1, 0)
			badge.BackgroundTransparency = 1
			badge.Font = Enum.Font.GothamBold
			badge.Text = "M"
			badge.TextColor3 = Color3.fromRGB(80, 255, 120)
			badge.TextSize = 13
			badge.TextStrokeTransparency = 0
			badge.TextXAlignment = Enum.TextXAlignment.Right
			badge.TextYAlignment = Enum.TextYAlignment.Top
			badge.Position = UDim2.new(1, -3, 0, 0)
			badge.Size = UDim2.fromOffset(14, 14)
			badge.Visible = hasTarget(per[name])
			badge.Parent = button

			cells[name] = {
				button = button,
				badge = badge
			}
			button.MouseButton1Click:Connect(function()
				pick(name)
			end)
		end
	end

